INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5661201, 822301, 29906, '<td valign="top">Oh what a priceless moment and beautiful shot! This scores 10 in my book.</td>', 'Oh what a priceless moment and beautiful shot! This scores 10 in my book.', '2009-09-24 23:55:04.000000', NULL, 1),
(5661203, 822166, 29906, '<td valign="top">I love your out-of-the-box thinking. Nice colors too.</td>', 'I love your out-of-the-box thinking. Nice colors too.', '2009-09-24 23:56:10.000000', NULL, 1),
(5661205, 822727, 29906, '<td valign="top">This is nice. Honest and authentic hug.</td>', 'This is nice. Honest and authentic hug.', '2009-09-24 23:56:34.000000', NULL, 1),
(5661207, 823118, 29906, '<td valign="top">This is adorable.</td>', 'This is adorable.', '2009-09-24 23:56:56.000000', NULL, 1),
(5661211, 822232, 29906, '<td valign="top">Definitely a nice concept. could score higher if the sharpness was better and the colors were not too pale. Nice shot still.</td>', 'Definitely a nice concept. could score higher if the sharpness was better and the colors were not too pale. Nice shot still.', '2009-09-24 23:58:47.000000', NULL, 1),
(5661983, 822521, 101445, '<td valign="top">by far the best of the challenge</td>', 'by far the best of the challenge', '2009-09-25 12:32:17.000000', NULL, 1),
(5662085, 822943, 45790, '<td valign="top">Cute take, but I don''t like the lighting -- too harsh.</td>', 'Cute take, but I don''t like the lighting -- too harsh.', '2009-09-25 13:28:59.000000', NULL, 1),
(5662086, 822230, 45790, '<td valign="top">Hug?? Kiss??</td>', 'Hug?? Kiss??', '2009-09-25 13:29:51.000000', NULL, 1),
(5662516, 822758, 103004, '<td valign="top">I love this one</td>', 'I love this one', '2009-09-25 19:55:27.000000', NULL, 1),
(5662672, 822412, 33672, '<td valign="top">Perfect tones.</td>', 'Perfect tones.', '2009-09-25 22:07:36.000000', NULL, 1),
(5662673, 823043, 33672, '<td valign="top">Nice work great comp.</td>', 'Nice work great comp.', '2009-09-25 22:07:52.000000', NULL, 1),
(5662741, 822972, 83313, '<td valign="top">I am tempted to start the voting of this challenge off by saying "Awwwwww!" and then copy and pasting it to everything else! <br/> <br/>Awwwwww!</td>', 'I am tempted to start the voting of this challenge off by saying "Awwwwww!" and then copy and pasting it to everything else!  Awwwwww!', '2009-09-25 23:13:34.000000', NULL, 1),
(5662743, 822990, 83313, '<td valign="top">Seems perhaps a touch too dim to really see the subjects. Other than that, Pretty good.</td>', 'Seems perhaps a touch too dim to really see the subjects. Other than that, Pretty good.', '2009-09-25 23:14:31.000000', NULL, 1),
(5662744, 822789, 83313, '<td valign="top">Awwwwww!</td>', 'Awwwwww!', '2009-09-25 23:15:03.000000', NULL, 1),
(5662755, 822832, 83313, '<td valign="top">What does this photo have to do with the subject?</td>', 'What does this photo have to do with the subject?', '2009-09-25 23:27:31.000000', NULL, 1),
(5662756, 822948, 83313, '<td valign="top">Giggly girls are the best kind.</td>', 'Giggly girls are the best kind.', '2009-09-25 23:27:56.000000', NULL, 1),
(5662761, 822641, 90414, '<td valign="top">I see blue in your future... beautiful image.</td>', 'I see blue in your future... beautiful image.', '2009-09-25 23:36:11.000000', NULL, 1),
(5662800, 822230, 83313, '<td valign="top">I suppose a hug and a kiss are implied, but otherwise I really can''t see how this fits.</td>', 'I suppose a hug and a kiss are implied, but otherwise I really can''t see how this fits.', '2009-09-26 00:09:34.000000', NULL, 1),
(5662807, 822999, 83313, '<td valign="top">I think this has some potential that could be brought out. White balance could use some adjustments is the first thing that strikes me. I think some other common tweaks such as curves, saturation contrast and sharpening would also help. In fact, I copied this into PaintShop Pro to see, and those adjustments did bring it up a notch.</td>', 'I think this has some potential that could be brought out. White balance could use some adjustments is the first thing that strikes me. I think some other common tweaks such as curves, saturation contrast and sharpening would also help. In fact, I copied this into PaintShop Pro to see, and those adjustments did bring it up a notch.', '2009-09-26 00:15:45.000000', NULL, 1),
(5662809, 822554, 83313, '<td valign="top">A very cute and endearing scene that appears to be hurt a bit by some harsh lighting.</td>', 'A very cute and endearing scene that appears to be hurt a bit by some harsh lighting.', '2009-09-26 00:16:47.000000', NULL, 1),
(5662817, 823054, 83313, '<td valign="top">Though cute and endearing, this appears to be a snapshot to me, I''m afraid. There is also excessive JPEG compression used, and the result is a lack of clarity and highly visible compression artifacts around the boy''s mouth and teeth. Compression kills detail. Always use the least compression you can get away with and still come in under challenge limits. (This entry is 43k and the challenge limit is 150k) Most image editors have that ability to adjust compression somewhere in the file save dialog.</td>', 'Though cute and endearing, this appears to be a snapshot to me, I''m afraid. There is also excessive JPEG compression used, and the result is a lack of clarity and highly visible compression artifacts around the boy''s mouth and teeth. Compression kills detail. Always use the least compression you can get away with and still come in under challenge limits. (This entry is 43k and the challenge limit is 150k) Most image editors have that ability to adjust compression somewhere in the file save dialog.', '2009-09-26 00:20:46.000000', NULL, 1),
(5662821, 823041, 83313, '<td valign="top">Very cute, but the close up, forward facing flash is a problem for this image. If you have a pop up or externally mounted flash, there are a few things that can be done to diffuse or bounce the light.</td>', 'Very cute, but the close up, forward facing flash is a problem for this image. If you have a pop up or externally mounted flash, there are a few things that can be done to diffuse or bounce the light.', '2009-09-26 00:22:50.000000', NULL, 1),
(5662823, 822827, 83313, '<td valign="top">Very sweet and sexy.</td>', 'Very sweet and sexy.', '2009-09-26 00:23:24.000000', NULL, 1),
(5662825, 822904, 83313, '<td valign="top">It seems a little soft on the detail, so I looked at the file size. There is some excessive JPEG compression taking away some detail, and visible artifacts on the faces. Your file size is only 42k and you could have used up to 150k for this challenge. Compression kills detail. Always use the least compression you can get away with and still come in under challenge limits.</td>', 'It seems a little soft on the detail, so I looked at the file size. There is some excessive JPEG compression taking away some detail, and visible artifacts on the faces. Your file size is only 42k and you could have used up to 150k for this challenge. Compression kills detail. Always use the least compression you can get away with and still come in under challenge limits.', '2009-09-26 00:25:10.000000', NULL, 1),
(5662827, 822451, 83313, '<td valign="top">Another Awwwwwww picture. So cute.</td>', 'Another Awwwwwww picture. So cute.', '2009-09-26 00:25:49.000000', NULL, 1),
(5662831, 821799, 83313, '<td valign="top">Looks like this was taken at a high ISO setting, plus heavy JPEG compression is adding visible pixelation. Your file size is only 35k and you could have used up to 150k for this challenge. Compression kills detail. Always use the least JPEG compression you can get away with and still come in under challenge limits.</td>', 'Looks like this was taken at a high ISO setting, plus heavy JPEG compression is adding visible pixelation. Your file size is only 35k and you could have used up to 150k for this challenge. Compression kills detail. Always use the least JPEG compression you can get away with and still come in under challenge limits.', '2009-09-26 00:28:17.000000', NULL, 1),
(5662841, 822727, 83313, '<td valign="top">I really like the color treatment here.</td>', 'I really like the color treatment here.', '2009-09-26 00:33:44.000000', NULL, 1),
(5662846, 822232, 83313, '<td valign="top">This makes me wonder what is going on. A play, perhaps? A couple of big problems I must mention:<br/> <br/>-composition needs some croppping. There is a lot of empty wall space on both sides that does nothing for the image. A tighter crop on the sides would aid.<br/> <br/>-Heavy compression is creating visible artifacts outlining both of the people. Compression kills detail. Always use the least compression you can get away with and still come in under challenge limits. Most image editors have that ability to adjust compression somewhere in the file save dialog.<br/> <br/>-His pants are falling down. (C''mon, you have to expect that comment from someone over 40)</td>', 'This makes me wonder what is going on. A play, perhaps? A couple of big problems I must mention: -composition needs some croppping. There is a lot of empty wall space on both sides that does nothing for the image. A tighter crop on the sides would aid. -Heavy compression is creating visible artifacts outlining both of the people. Compression kills detail. Always use the least compression you can get away with and still come in under challenge limits. Most image editors have that ability to adjust compression somewhere in the file save dialog. -His pants are falling down. (C''mon, you have to expect that comment from someone over 40)', '2009-09-26 00:38:48.000000', NULL, 1),
